function AvatarPreload() {
  const { user } = useAccount()
  // Use the login transition to prepare the exact original, not a low-detail copy.
  useEffect(() => {
    clearAvatarAssets()
    if (user) void loadAvatarBytes('queen').catch(() => { /* The world offers explicit retry. */ })
    return clearAvatarAssets
  }, [user?.id])
  return null
}

/* Compact original-brand strip: artwork remains unmodified and uncropped. */
.brand-showcase { padding-top: 22px; margin-bottom: 32px; }
.brand-showcase-heading { margin-bottom: 18px; }
.brand-showcase-heading h2 { font-size: clamp(25px, 2.5vw, 34px); }
.brand-showcase-grid { grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 10px; }
.brand-banner { padding: 14px 12px 11px; border-radius: 12px; }
.brand-banner-top { font-size: 8px; letter-spacing: .06em; }
.brand-banner-index, .brand-banner > p { display: none; }
.brand-banner-logo { height: 64px; gap: 5px; }
.brand-banner .brand-banner-logo img { width: 100%; max-width: 150px; height: 44px; object-fit: contain; }
.brand-banner--forge .brand-banner-logo img { width: 28px; height: 36px; }
.brand-banner--forge .brand-banner-logo > span { font-size: 16px; }
.brand-banner-action { min-height: 32px; font-size: 10px; padding-top: 8px; gap: 4px; }
.iss-petition { display: flex; align-items: center; gap: 28px; margin-top: 20px; padding: 24px; border: 1px solid #6dd7c94d; border-radius: 16px; background: linear-gradient(120deg, #12343a, #0c1928); }
.iss-petition > div { flex: 1; }
.iss-petition h2 { margin: 8px 0 10px; font-size: clamp(23px, 2.4vw, 31px); }
.iss-petition p { color: #d6e5ec; font-size: 14px; line-height: 1.65; margin: 0 0 8px; max-width: 760px; }
.iss-petition small { color: #9db5c4; font-size: 11px; line-height: 1.5; }
.iss-petition-sign { flex-shrink: 0; display: inline-flex; gap: 16px; align-items: center; justify-content: center; min-height: 48px; padding: 12px 20px; border-radius: 10px; background: #b8efda; color: #102b29; font-weight: 750; text-decoration: none; }
.iss-petition-sign:focus-visible { outline: 3px solid white; outline-offset: 4px; }
@media (max-width: 1100px) { .brand-showcase-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
@media (max-width: 620px) {
  .brand-showcase-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .iss-petition { align-items: stretch; flex-direction: column; padding: 19px; gap: 18px; }
}
@media (max-width: 340px) { .brand-showcase-grid { grid-template-columns: 1fr; } }

/* Original planetary map images; gradient remains a network-failure fallback. */
.planet-visual { min-height: 290px; background-color: #050d19; }
.planet-sphere { width: 200px; height: 200px; right: calc(50% - 100px); top: 32px; background-size: auto 100%; background-repeat: repeat-x; background-position: 45% center; box-shadow: inset -48px -12px 45px #000b, inset 6px 3px 14px #ffffff25, 0 0 35px #7196cf30; animation: planet-map-turn 100s linear infinite; }
.planet-mercury { background-image: url('https://www.solarsystemscope.com/textures/download/2k_mercury.jpg'), linear-gradient(135deg,#c5b9a4,#6e6256); }
.planet-venus { background-image: url('https://www.solarsystemscope.com/textures/download/2k_venus_atmosphere.jpg'), linear-gradient(135deg,#f1c17f,#8c4f2d); }
.planet-earth { background-image: url('https://www.solarsystemscope.com/textures/download/2k_earth_daymap.jpg'), linear-gradient(135deg,#59bce5,#2b6f4e); box-shadow: inset -48px -12px 45px #000b, inset 5px 2px 12px #e5f8ff66, 0 0 18px #499df85c; }
.planet-mars { background-image: url('https://www.solarsystemscope.com/textures/download/2k_mars.jpg'), linear-gradient(135deg,#e47c52,#7b2f27); }
.planet-jupiter { background-image: url('https://www.solarsystemscope.com/textures/download/2k_jupiter.jpg'), linear-gradient(135deg,#ead3ad,#b87954); }
.planet-saturn { background-image: url('https://www.solarsystemscope.com/textures/download/2k_saturn.jpg'), linear-gradient(135deg,#e7d39d,#9d8357); }
.planet-uranus { background-image: url('https://www.solarsystemscope.com/textures/download/2k_uranus.jpg'), linear-gradient(135deg,#b4edf1,#4ba1ae); }
.planet-neptune { background-image: url('https://www.solarsystemscope.com/textures/download/2k_neptune.jpg'), linear-gradient(135deg,#5c8df1,#1b347a); }
.planet-saturn-rings { position: absolute; width: 310px; height: 88px; left: calc(50% - 155px); top: 95px; border-radius: 50%; border: 21px double #d4c496a8; transform: rotate(-25deg); clip-path: polygon(0 50%, 100% 50%, 100% 100%, 0 100%); box-shadow: 0 5px 10px #0006; }
.planet-texture-credit { color: #a5c4ce; font-size: 10px; line-height: 1.5; }
.planet-texture-credit a { color: #cae7e8; }
.planet-flight-line { bottom: 28px; opacity: .45; }
.planet-rover { bottom: 29px; }
@keyframes planet-map-turn { from { background-position: 45% center; } to { background-position: 245% center; } }
@media (prefers-reduced-motion: reduce) { .planet-sphere { animation: none; } }

